-- Seed cities data for Itinera
-- Run: supabase db push (or paste into Supabase SQL editor)

INSERT INTO public.cities (name, country, country_code, description, tags, best_time_to_visit, timezone, currency, language, family_tips, safety_notes) VALUES
('Amsterdam', 'Netherlands', 'NL', 'A city of canals, cycling culture, and world-class museums. Amsterdam charms visitors with its narrow canal houses, vibrant nightlife, and incredible art heritage.', ARRAY['canals','cycling','museums','nightlife','culture'], 'April–May or September–October', 'Europe/Amsterdam', 'EUR', 'Dutch', 'Canal boat tours are a must with kids. The NEMO Science Museum and Artis Zoo are family highlights. Rent cargo bikes to explore like a local.', 'Generally very safe. Watch bikes on cycle paths and keep an eye on belongings in busy tourist areas.'),

('Athens', 'Greece', 'GR', 'The cradle of Western civilisation, Athens blends ancient ruins with a buzzing contemporary city. Walk in the footsteps of Socrates and enjoy spectacular Acropolis views.', ARRAY['history','ancient ruins','culture','food','architecture'], 'March–May or September–November', 'Europe/Athens', 'EUR', 'Greek', 'The Acropolis Museum has child-friendly exhibits. Avoid midday heat in summer. The Panathenaic Stadium is free and fascinating for all ages.', 'Very safe for tourists. Be cautious of pickpockets around major sights and on the metro.'),

('Auckland', 'New Zealand', 'NZ', 'New Zealand''s largest city sits on an isthmus between two harbours and features a striking skyline anchored by Sky Tower, world-class dining, and stunning coastal scenery.', ARRAY['harbour','outdoor','culture','food','adventure'], 'December–February (summer)', 'Pacific/Auckland', 'NZD', 'English', 'Waitemata Harbour ferry rides are great for kids. Kelly Tarlton''s Sea Life Aquarium is a family favourite. Rangitoto Island day trip is accessible for older children.', 'Very safe city. Standard urban precautions apply.'),

('Bali', 'Indonesia', 'ID', 'An island of spiritual temples, lush terraced rice fields, and pristine surf beaches. Bali offers a magical blend of Hindu culture, warm hospitality, and tropical beauty.', ARRAY['beaches','temples','culture','wellness','nature'], 'April–October (dry season)', 'Asia/Makassar', 'IDR', 'Balinese/Indonesian', 'Water parks in Seminyak suit younger kids. Ubud''s Monkey Forest delights children. Choose family-friendly resorts in Nusa Dua for calmer beaches.', 'Generally safe. Watch currents at surf beaches. Drink bottled water only. Respect temple dress codes.'),

('Bangkok', 'Thailand', 'TH', 'Thailand''s frenetic capital dazzles with ornate temples, floating markets, and legendary street food. Bangkok never sleeps and rewards curious travellers at every turn.', ARRAY['temples','street food','markets','nightlife','culture'], 'November–February', 'Asia/Bangkok', 'THB', 'Thai', 'Chao Phraya river boats are thrilling for kids. Safari World and Dream World theme parks are local favourites. Dress children modestly for temple visits.', 'Generally safe for tourists. Use metered taxis or Grab. Stay hydrated in tropical heat.'),

('Barcelona', 'Spain', 'ES', 'Gaudí''s fantastical architecture, sun-drenched beaches, and world-class tapas make Barcelona one of Europe''s most captivating cities. Art, food, and football reign supreme.', ARRAY['architecture','beaches','food','art','nightlife'], 'May–June or September–October', 'Europe/Madrid', 'EUR', 'Catalan/Spanish', 'Park Güell and Sagrada Família wow children with Gaudí''s fairy-tale shapes. Barceloneta beach is family-friendly. CosmoCaixa science museum is excellent for kids.', 'Generally safe. Watch for pickpockets on Las Ramblas and busy metro lines.'),

('Berlin', 'Germany', 'DE', 'Germany''s reunified capital is a city of radical reinvention — raw, creative, and culturally explosive. Cold War history meets cutting-edge art and Europe''s best club scene.', ARRAY['history','culture','art','nightlife','food'], 'May–September', 'Europe/Berlin', 'EUR', 'German', 'The Natural History Museum and Legoland Discovery Centre are children''s favourites. Tiergarten park is perfect for picnics. The Deutsches Technikmuseum is hands-on fun.', 'Very safe. Standard urban precautions apply. Excellent public transport.'),

('Brussels', 'Belgium', 'BE', 'The heart of Europe, Brussels charms with its ornate Grand Place, incredible chocolate and beer culture, and a surprisingly vibrant art nouveau architecture scene.', ARRAY['history','food','chocolate','architecture','politics'], 'April–June or September–October', 'Europe/Brussels', 'EUR', 'French/Dutch/German', 'Mini-Europe and Atomium delight children. The Natural Sciences Museum has impressive dinosaur skeletons. Belgian waffles and chocolate are a hit with all ages.', 'Generally safe. Be alert to pickpockets in tourist areas and on public transport.'),

('Budapest', 'Hungary', 'HU', 'Hungary''s stunning capital straddles the Danube with magnificent architecture, legendary thermal baths, and a vibrant ruin bar culture that has captured the imagination of travellers worldwide.', ARRAY['thermal baths','architecture','history','food','nightlife'], 'April–May or September–October', 'Europe/Budapest', 'HUF', 'Hungarian', 'Széchenyi Baths have family-friendly pools. Budapest Zoo is one of Europe''s oldest. The Labyrinth of Buda Castle is a dramatic underground adventure for older kids.', 'Very safe. Standard tourist precautions apply.'),

('Buenos Aires', 'Argentina', 'AR', 'South America''s "Paris" dazzles with its grand European-style boulevards, passionate tango culture, world-class steak, and an irrepressibly stylish population.', ARRAY['culture','food','tango','architecture','nightlife'], 'March–May or September–November', 'America/Argentina/Buenos_Aires', 'ARS', 'Spanish', 'Palermo parks are great for families. The interactive children''s museum Malba has engaging exhibits. La Boca neighbourhood is colourful but explore during daylight hours.', 'Exercise normal caution. Avoid displaying expensive electronics in public. Use radio taxis or Uber.'),

('Cape Town', 'South Africa', 'ZA', 'Dramatic Table Mountain forms the backdrop to one of the world''s most beautiful cities. Cape Town mesmerises with its wine lands, white beaches, and extraordinary history.', ARRAY['nature','beaches','mountains','wine','wildlife'], 'November–March (summer)', 'Africa/Johannesburg', 'ZAR', 'English/Afrikaans/Xhosa', 'Boulders Beach penguin colony is magical for children. The Two Oceans Aquarium is superb. Cable car up Table Mountain is thrilling for older kids.', 'Exercise caution especially after dark. Stick to well-known tourist areas and use reputable transport.'),

('Copenhagen', 'Denmark', 'DK', 'Scandinavia''s cool capital is a model of sustainable urban living. Copenhagen offers exceptional cuisine, fairytale architecture, and the world''s happiest people.', ARRAY['design','cycling','food','culture','sustainability'], 'May–August', 'Europe/Copenhagen', 'DKK', 'Danish', 'Tivoli Gardens is a legendary family amusement park. The National Museum has free family exhibits. Nyhavn harbour boat tours delight children of all ages.', 'One of the safest cities in the world. Very family-friendly infrastructure.'),

('Dubai', 'United Arab Emirates', 'AE', 'A futuristic desert metropolis of record-breaking architecture, luxury shopping, and year-round sunshine. Dubai reinvents itself constantly while blending ancient traditions with tomorrow''s ambitions.', ARRAY['luxury','architecture','shopping','beaches','adventure'], 'November–March', 'Asia/Dubai', 'AED', 'Arabic', 'Dubai Frame and children''s city at Creek Park are great for kids. IMG Worlds of Adventure is the world''s largest indoor theme park. The Dubai Fountain show is spectacular for all ages.', 'Very safe city. Respect local laws and dress codes, especially during Ramadan.'),

('Dublin', 'Ireland', 'IE', 'Ireland''s vibrant capital warms visitors with legendary pub culture, Georgian architecture, world-class literary heritage, and some of the friendliest people on earth.', ARRAY['pubs','history','literature','culture','music'], 'May–September', 'Europe/Dublin', 'EUR', 'English/Irish', 'Dublin Zoo in Phoenix Park is excellent for families. The National Museum and Gallery are free. Viking Splash Tours are thrilling water-and-road adventures for kids.', 'Very safe city. Standard urban precautions apply.'),

('Dubrovnik', 'Croatia', 'HR', 'The "Pearl of the Adriatic" stuns with its perfectly preserved medieval walled city, crystal-clear waters, and Game of Thrones filming locations. Croatia''s most iconic destination.', ARRAY['beaches','history','architecture','sailing','culture'], 'May–June or September', 'Europe/Zagreb', 'EUR', 'Croatian', 'Walking the city walls is accessible for older children. Cable car to Mount Srđ offers amazing views. Nearby Lokrum island is a perfect family day trip.', 'Very safe. Main challenge is summer overcrowding. Visit early morning to beat cruise ship crowds.'),

('Edinburgh', 'Scotland', 'GB', 'Scotland''s dramatic capital perches atop volcanic crags. Edinburgh''s medieval Old Town and Georgian New Town, its castle, and its world-famous Fringe Festival make it unforgettable.', ARRAY['castle','history','festivals','whisky','culture'], 'May–September', 'Europe/London', 'GBP', 'English/Scottish Gaelic', 'Edinburgh Castle is excellent for children with its interactive exhibits. Dynamic Earth science centre is hands-on fun. Arthur''s Seat hike suits older kids for panoramic views.', 'Very safe city. Weather can be unpredictable — always carry layers.'),

('Helsinki', 'Finland', 'FI', 'Finland''s compact, beautifully designed capital sits on a peninsula surrounded by a stunning archipelago. Helsinki excels in design, saunas, and pristine Nordic nature.', ARRAY['design','nature','culture','saunas','architecture'], 'June–August or December–February (Northern Lights)', 'Europe/Helsinki', 'EUR', 'Finnish/Swedish', 'Linnanmäki amusement park is a family classic. Heureka Science Centre has spectacular hands-on exhibits. The Natural History Museum is free for children.', 'One of the safest capitals in the world. Very family-friendly.'),

('Hong Kong', 'China', 'HK', 'Asia''s world city dazzles with its neon-lit skyline, legendary dim sum culture, and a fascinating collision of Chinese heritage and British colonial history.', ARRAY['skyline','food','shopping','culture','hiking'], 'October–December', 'Asia/Hong_Kong', 'HKD', 'Cantonese/English', 'Ocean Park is a spectacular family theme park. The Star Ferry and cable tram rides delight all ages. Disneyland Hong Kong is a classic family destination.', 'Very safe city. Extremely efficient public transport. Keep belongings secure in crowds.'),

('Krakow', 'Poland', 'PL', 'Poland''s former royal capital enchants with its well-preserved medieval centre, sobering Holocaust history, and an exceptional café culture centred around Europe''s largest medieval square.', ARRAY['history','architecture','culture','food','nightlife'], 'April–June or September–October', 'Europe/Warsaw', 'PLN', 'Polish', 'Dragon''s Den at Wawel Castle is a hit with kids. The interactive Museum of Municipal Engineering is engaging. The Wieliczka Salt Mine is a spectacular underground world.', 'Very safe city. Standard precautions in busy tourist areas.'),

('Kuala Lumpur', 'Malaysia', 'MY', 'Malaysia''s dynamic capital gleams with the iconic Petronas Twin Towers. KL offers an extraordinary blend of Malay, Chinese, and Indian cultures with world-class shopping and street food.', ARRAY['skyscrapers','food','culture','shopping','nature'], 'May–July', 'Asia/Kuala_Lumpur', 'MYR', 'Malay', 'KL Bird Park is one of the world''s largest free-flight aviaries. Sunway Lagoon water park is brilliant for families. The KLCC Aquaria is impressive for children.', 'Generally safe. Use Grab for transport. Stay hydrated in tropical heat.'),

('Kyoto', 'Japan', 'JP', 'Japan''s ancient imperial capital is a living museum of traditional culture. Kyoto''s 1,600 temples, tea ceremony traditions, and geisha districts offer an unmatched glimpse into classical Japan.', ARRAY['temples','culture','tradition','food','nature'], 'March–May or October–November', 'Asia/Tokyo', 'JPY', 'Japanese', 'Fushimi Inari torii gates are fascinating for children. Arashiyama bamboo grove is magical. Nijo Castle has nightingale floors that intrigue kids. Deer in Nara (nearby) are always a hit.', 'Extremely safe. Very family-friendly. Excellent public transport.'),

('Lisbon', 'Portugal', 'PT', 'Europe''s sunniest capital cascades down seven hills to the Tagus River. Lisbon charms with its fado music, golden pastéis de nata, historic trams, and a genuine, unhurried warmth.', ARRAY['culture','food','trams','history','fado'], 'March–May or September–October', 'Europe/Lisbon', 'EUR', 'Portuguese', 'Lisbon Oceanarium is world-class and magical for children. Historic tram 28 ride is an adventure for all ages. Sintra palaces make a superb family day trip.', 'Very safe. Watch for steep hills and slippery cobblestones. Petty theft in touristy tram 28.'),

('London', 'United Kingdom', 'GB', 'The world''s most visited city offers extraordinary museums, iconic landmarks, world-class theatre, and an unparalleled diversity of cultures, cuisines, and experiences.', ARRAY['museums','history','culture','theatre','food'], 'May–September', 'Europe/London', 'GBP', 'English', 'Most major museums are free including the Natural History Museum and Science Museum — perfect for families. Hyde Park, the London Eye, and the Tower of London are classic family experiences.', 'Generally safe. Be alert to pickpockets in tourist areas and on the Tube. Use licensed taxis or Uber.'),

('Los Angeles', 'United States', 'US', 'The entertainment capital of the world sprawls across sunny Southern California. LA offers Hollywood glamour, world-class beaches, diverse neighbourhoods, and incredible year-round weather.', ARRAY['entertainment','beaches','culture','food','nature'], 'March–May or September–November', 'America/Los_Angeles', 'USD', 'English', 'Universal Studios and Disneyland are iconic family destinations. The La Brea Tar Pits are fascinating for children. Santa Monica Pier is a classic family outing.', 'Exercise caution in certain neighbourhoods. A car is essential. Never leave valuables in vehicles.'),

('Madrid', 'Spain', 'ES', 'Spain''s passionate capital lives life at full volume. Madrid offers Europe''s finest art museums, legendary tapas culture, the world''s oldest restaurant, and an electrifying football scene.', ARRAY['art','food','football','culture','nightlife'], 'April–June or September–October', 'Europe/Madrid', 'EUR', 'Spanish', 'Retiro Park is a wonderful family space with rowing boats. The Natural History Museum is free and fascinating. The Prado''s family guide makes great art accessible to children.', 'Generally safe. Standard precautions around Puerta del Sol. Watch for pickpockets on busy metro lines.'),

('Marrakech', 'Morocco', 'MA', 'Morocco''s rose-red city ignites the senses with its medieval medina, colourful souks, spice-laden air, and the legendary Djemaa el-Fna square that erupts into extraordinary life each evening.', ARRAY['souks','culture','food','architecture','history'], 'March–May or September–November', 'Africa/Casablanca', 'MAD', 'Arabic/Darija', 'Jardin Majorelle botanical garden is beautiful for all ages. Camel rides are a hit with children. Explore the medina with a guide to navigate safely and learn local history.', 'Generally safe in tourist areas. Use licensed guides for the medina. Dress modestly. Be firm but polite with persistent vendors.'),

('Melbourne', 'Australia', 'AU', 'Australia''s cultural capital thrives on its legendary café culture, street art, world-class sporting events, and a buzzing arts scene that puts it among the world''s most liveable cities.', ARRAY['coffee','culture','food','sport','art'], 'March–May or September–November', 'Australia/Melbourne', 'AUD', 'English', 'Melbourne Zoo and SEA LIFE Aquarium are excellent for children. Scienceworks museum is hands-on fun. The historic tram network is an adventure in itself.', 'Very safe city. Excellent public transport. Watch for fast lane-switching by trams.'),

('Mexico City', 'Mexico', 'MX', 'One of the Americas'' great megacities pulses with extraordinary energy. Mexico City''s world-class museums, UNESCO heritage sites, and revolutionary street food scene reward adventurous travellers.', ARRAY['history','food','culture','art','architecture'], 'March–May or October–November', 'America/Mexico_City', 'MXN', 'Spanish', 'Papalote Children''s Museum is outstanding. Xochimilco floating gardens are a unique family outing. The anthropology museum has spectacular pre-Columbian exhibits.', 'Exercise caution and use Uber or radio taxis rather than hailing cabs on the street. Stick to tourist-friendly neighbourhoods.'),

('Miami', 'United States', 'US', 'Florida''s glamorous gateway sizzles with Art Deco architecture, turquoise waters, Latin rhythms, and an extraordinary multicultural energy that makes it one of America''s most exciting cities.', ARRAY['beaches','nightlife','culture','food','art'], 'November–April', 'America/New_York', 'USD', 'English', 'South Beach is family-friendly with lifeguards. Miami Children''s Museum is excellent. The Everglades airboat tours are thrilling for older children.', 'Generally safe in tourist areas. Standard precautions apply. Use Uber for late-night travel.'),

('Milan', 'Italy', 'IT', 'Italy''s fashion and design capital is also a city of extraordinary art — home to Leonardo''s Last Supper and the world''s most prestigious opera house, La Scala.', ARRAY['fashion','art','design','food','culture'], 'April–May or September–October', 'Europe/Rome', 'EUR', 'Italian', 'Leonardo da Vinci Science Museum is superb for children. Parco Sempione near Sforzesco Castle is great for families. Milan''s gelato and pizza are universally loved by kids.', 'Generally safe. Be vigilant about pickpockets around the Duomo and central station.'),

('Montreal', 'Canada', 'CA', 'Quebec''s largest city is a vibrant blend of French and English cultures. Montreal''s remarkable festivals, world-class bagels, and thriving arts scene create a uniquely North American joie de vivre.', ARRAY['culture','food','festivals','bilingual','art'], 'June–September', 'America/Toronto', 'CAD', 'French/English', 'Biodome and Insectarium are exceptional for children. La Ronde amusement park is a summer favourite. The Old Port waterfront has excellent family activities in summer.', 'Very safe city. Very bilingual — French is the primary language but English is widely spoken.'),

('Munich', 'Germany', 'DE', 'Bavaria''s magnificent capital combines world-famous Oktoberfest celebrations with remarkable museums, stunning palaces, and easy access to the Bavarian Alps for outdoor adventures.', ARRAY['beer','culture','history','alps','food'], 'May–September or December (Christmas markets)', 'Europe/Berlin', 'EUR', 'German', 'Deutsches Museum is one of the world''s greatest science museums and perfect for children. English Garden has incredible children''s play areas. Nymphenburg Palace gardens are beautiful for families.', 'Very safe. Excellent public transport. Standard precautions around Oktoberfest period.'),

('New York City', 'United States', 'US', 'The city that never sleeps is the ultimate urban experience. New York''s iconic skyline, extraordinary cultural institutions, diverse neighbourhoods, and relentless energy inspire millions of visitors annually.', ARRAY['skyline','culture','food','art','entertainment'], 'April–June or September–November', 'America/New_York', 'USD', 'English', 'Central Park, the American Museum of Natural History, and the Intrepid Museum are outstanding for children. The Staten Island Ferry is free with spectacular Statue of Liberty views.', 'Generally safe in tourist areas. Keep belongings secure on the subway. Avoid displaying expensive items.'),

('Nice', 'France', 'FR', 'The jewel of the French Riviera, Nice enchants with its famous Promenade des Anglais, old town pastel facades, luminous Mediterranean light, and superb Niçoise cuisine.', ARRAY['beaches','riviera','food','culture','art'], 'May–September', 'Europe/Paris', 'EUR', 'French', 'The Promenade des Anglais is perfect for family cycling. Castle Hill park has wonderful views and playground areas. The pebbly beach is manageable for children with beach shoes.', 'Very safe. Watch for pickpockets on busy beachfronts. Water shoes recommended for pebbly beaches.'),

('Osaka', 'Japan', 'JP', 'Japan''s kitchen capital is a city of extraordinary energy, spectacular street food, and infectious friendliness. Osaka''s castle, comedy culture, and Dotonbori neon make it utterly loveable.', ARRAY['food','culture','entertainment','shopping','history'], 'March–April or October–November', 'Asia/Tokyo', 'JPY', 'Japanese', 'Universal Studios Japan is world-class for children. Osaka Aquarium Kaiyukan is one of the world''s best. Osaka Castle park is wonderful for family picnics.', 'Extremely safe. Very welcoming to families. Excellent subway system.'),

('Paris', 'France', 'FR', 'The City of Light needs no introduction. Paris captivates with the Eiffel Tower, world''s greatest art museum, exquisite cuisine, and a romantic atmosphere that has inspired artists for centuries.', ARRAY['art','culture','food','romance','history'], 'April–June or September–October', 'Europe/Paris', 'EUR', 'French', 'Disneyland Paris is a classic family destination. The Eiffel Tower and Sacré-Cœur delight children. Luxembourg Gardens has excellent playgrounds. Musée d''Orsay is manageable for children with its Impressionist masterpieces.', 'Generally safe. Be vigilant of pickpockets around Eiffel Tower, Louvre, and on the metro.'),

('Porto', 'Portugal', 'PT', 'Portugal''s charismatic second city enchants with its dramatic hillside setting, decorated azulejo-tiled buildings, port wine cellars, and a magnificent six-arch bridge by Eiffel''s company.', ARRAY['wine','history','culture','food','architecture'], 'May–September', 'Europe/Lisbon', 'EUR', 'Portuguese', 'The Serralves Museum has an excellent children''s programme. The iconic Dom Luís I bridge walk is an adventure. Day trips to beaches along the Costa Verde are perfect for families.', 'Very safe. Watch for slippery cobblestones on steep hills. Standard precautions in busy areas.'),

('Prague', 'Czech Republic', 'CZ', 'One of Europe''s most beautiful capitals, Prague''s perfectly preserved medieval architecture, dramatic castle, and legendary beer culture combine to create a genuinely fairy-tale city.', ARRAY['history','architecture','beer','culture','nightlife'], 'May–June or September–October', 'Europe/Prague', 'CZK', 'Czech', 'Prague Castle is excellent for children with its colourful changing of the guard. The Astronomical Clock hour chime delights all ages. Boat trips on the Vltava are family-friendly.', 'Very safe. Prague is extremely tourist-friendly. Standard precautions in busy Old Town areas.'),

('Reykjavik', 'Iceland', 'IS', 'The world''s northernmost capital is the gateway to Iceland''s extraordinary natural wonders — geysers, waterfalls, volcanoes, and the Northern Lights create an other-worldly experience.', ARRAY['northern lights','nature','geysers','culture','adventure'], 'June–August or October–March (Northern Lights)', 'Atlantic/Reykjavik', 'ISK', 'Icelandic', 'The Blue Lagoon has family options (though expensive). Whale watching tours are spectacular. The Perlan Museum''s Northern Lights show is great for children year-round.', 'Extremely safe — one of the world''s safest countries. Weather can change rapidly; always carry layers.'),

('Rio de Janeiro', 'Brazil', 'BR', 'Brazil''s breathtakingly beautiful "Marvellous City" stuns with Christ the Redeemer, Copacabana and Ipanema beaches, samba rhythms, and a passion for life that is entirely infectious.', ARRAY['beaches','carnival','culture','nature','samba'], 'April–June or September–October (outside Carnival)', 'America/Sao_Paulo', 'BRL', 'Portuguese', 'Sugar Loaf cable car is thrilling for all ages. Tijuca National Park offers accessible nature trails. The Botanical Garden is beautiful for a family stroll.', 'Exercise caution and use Uber or trusted transport. Stick to busy tourist beaches. Avoid remote areas, especially after dark.'),

('Rome', 'Italy', 'IT', 'The Eternal City overwhelms with its extraordinary density of history — the Colosseum, Forum, Vatican, and Pantheon create a living museum unlike anywhere else on earth.', ARRAY['history','art','food','architecture','culture'], 'April–May or September–October', 'Europe/Rome', 'EUR', 'Italian', 'Tossing a coin in the Trevi Fountain is magical for children. The Colosseum and Gladiator''s Gate junior programme engages kids. Borghese Gallery''s sculpture makes art accessible. Gelato everywhere!', 'Generally safe. Watch for pickpockets around tourist sites and on buses. Validate transit tickets to avoid fines.'),

('San Francisco', 'United States', 'US', 'Perched on dramatic hills above the bay, San Francisco enchants with the Golden Gate Bridge, iconic cable cars, colourful Victorian architecture, and a culture of extraordinary innovation.', ARRAY['bay','bridges','culture','food','technology'], 'September–November', 'America/Los_Angeles', 'USD', 'English', 'The Exploratorium is one of the world''s best hands-on science museums for children. Cable car rides are a classic family thrill. Alcatraz tour is excellent for older children.', 'Exercise caution in the Tenderloin and certain SoMa areas. Generally safe in tourist neighbourhoods.'),

('Seoul', 'South Korea', 'KR', 'South Korea''s dynamic capital is a stunning combination of ancient palaces, cutting-edge technology, K-pop culture, and one of Asia''s most extraordinary culinary scenes.', ARRAY['kpop','technology','food','culture','history'], 'April–May or September–November', 'Asia/Seoul', 'KRW', 'Korean', 'Lotte World is one of the world''s largest indoor theme parks. The Children''s Grand Park zoo and amusement area is family-friendly. Gyeongbokgung Palace guard changing ceremony thrills children.', 'Extremely safe. Very family-friendly. Excellent metro system with English signage throughout.'),

('Seville', 'Spain', 'ES', 'Andalusia''s passionate capital is the birthplace of flamenco and home to the world''s largest Gothic cathedral. Seville''s orange-blossom scented streets and vibrant tapas culture make it irresistible.', ARRAY['flamenco','history','culture','food','architecture'], 'March–May or September–November', 'Europe/Madrid', 'EUR', 'Spanish', 'Real Alcázar palace gardens enchant children with their beauty. Horse-drawn carriage rides around the city are a family favourite. Isla Mágica theme park is perfect for children.', 'Very safe. Extremely hot in July–August; plan outdoor activities for early morning and evening.'),

('Singapore', 'Singapore', 'SG', 'Asia''s most polished city-state dazzles with Gardens by the Bay, extraordinary hawker food culture, and a seamless blend of Chinese, Malay, and Indian traditions in an immaculate modern setting.', ARRAY['food','culture','gardens','technology','shopping'], 'February–April', 'Asia/Singapore', 'SGD', 'English', 'Gardens by the Bay and the Children''s Garden are magical. Singapore Zoo with its night safari is world-class. Universal Studios Singapore and Adventure Cove Waterpark are exceptional for families.', 'One of the safest cities in the world. Strict laws — research what''s prohibited before visiting. Excellent public transport.'),

('Stockholm', 'Sweden', 'SE', 'Scandinavia''s elegant capital spreads across 14 islands where Lake Mälaren meets the Baltic Sea. Stockholm''s extraordinary ABBA Museum, Vasa warship, and Djurgården island create a magnificent visitor experience.', ARRAY['design','history','culture','nature','food'], 'May–September', 'Europe/Stockholm', 'SEK', 'Swedish', 'Junibacken children''s museum celebrating Pippi Longstocking and Astrid Lindgren is magical. The Vasa Museum''s 17th-century warship astonishes all ages. Skansen open-air museum is superb for families.', 'Extremely safe. Very family-friendly. Excellent public transport including ferries between islands.'),

('Sydney', 'Australia', 'AU', 'Australia''s most iconic city shines with its harbour-side Opera House, Bondi Beach, and an outdoor lifestyle built around sun, surf, and spectacular scenery.', ARRAY['harbour','beaches','culture','food','outdoor'], 'September–November or March–May', 'Australia/Sydney', 'AUD', 'English', 'Taronga Zoo with Opera House views is magical for families. The Australian Museum and Powerhouse Museum are excellent for children. Bondi to Coogee coastal walk suits older children.', 'Very safe. Be sun-smart — UV is extreme. Swim between the flags at patrolled beaches. Wildlife encounters: be cautious of spiders and snakes in bush areas.'),

('Tokyo', 'Japan', 'JP', 'Japan''s extraordinary capital is arguably the world''s greatest city — mind-boggling in scale yet hyperefficient, Tokyo seamlessly blends ancient temples with neon-lit technological wonder.', ARRAY['technology','culture','food','anime','fashion'], 'March–April or October–November', 'Asia/Tokyo', 'JPY', 'Japanese', 'DisneySea and Disneyland Tokyo are world''s best. teamLab digital art museum astonishes children. Shibuya crossing crossing and Harajuku fashions fascinate older kids. Ramen and sushi are usually a hit.', 'Extraordinarily safe. Japan is one of the world''s safest destinations. Excellent public transport — get a Suica card.'),

('Toronto', 'Canada', 'CA', 'Canada''s largest and most multicultural city skylines around the iconic CN Tower and offers world-class museums, a thriving food scene representing over 200 nationalities, and easy access to Niagara Falls.', ARRAY['culture','food','multiculturalism','cn tower','nature'], 'May–September', 'America/Toronto', 'CAD', 'English', 'Royal Ontario Museum and Ontario Science Centre are outstanding for families. Centre Island is a wonderful family day trip. Niagara Falls day trip is unmissable for all ages.', 'Very safe city. Standard urban precautions. Excellent public transport.'),

('Vancouver', 'Canada', 'CA', 'Framed by mountains, ocean, and forest, Vancouver is North America''s most naturally beautiful city. Stanley Park, Whistler ski resort, and exceptional Pacific Rim cuisine make it extraordinary.', ARRAY['nature','mountains','ocean','outdoor','food'], 'June–September', 'America/Vancouver', 'CAD', 'English', 'Stanley Park with its aquarium and water park is superb for families. Granville Island public market is fascinating for children. Grouse Mountain gondola and wildlife refuge delight all ages.', 'Very safe. Excellent public transport. Be aware of bear activity when hiking trails.'),

('Venice', 'Italy', 'IT', 'The world''s most improbable city rises from its lagoon on millions of wooden piles. Venice''s labyrinthine canals, magnificent palaces, and Carnival traditions make it an unforgettable wonder.', ARRAY['canals','art','history','architecture','romance'], 'April–May or October–November', 'Europe/Rome', 'EUR', 'Italian', 'Gondola rides are magical for children. The Doge''s Palace has family audio guides. Murano glass-blowing demonstrations fascinate all ages. Vaporetto water buses are an adventure in themselves.', 'Very safe. Plan route in advance — it''s easy to get lost in the labyrinthine streets. Watch for high water (acqua alta) in autumn/winter.'),

('Vienna', 'Austria', 'AT', 'The City of Music enchants with Habsburg grandeur, extraordinary art history, Sacher torte, and the world''s finest concert halls. Vienna regularly tops quality-of-life rankings worldwide.', ARRAY['music','culture','history','food','architecture'], 'April–May or September–October', 'Europe/Vienna', 'EUR', 'German', 'Prater amusement park with the historic Giant Ferris Wheel is a family classic. The Natural History Museum is outstanding. Schönbrunn Palace has a children''s museum and maze.', 'Extremely safe. One of Europe''s most liveable cities. Excellent public transport.'),

('Warsaw', 'Poland', 'PL', 'Heroically rebuilt from wartime rubble, Poland''s resilient capital pairs its moving historical narrative with a booming contemporary scene of tech innovation, hipster coffee culture, and excellent cuisine.', ARRAY['history','culture','resilience','food','nightlife'], 'May–September', 'Europe/Warsaw', 'PLN', 'Polish', 'Copernicus Science Centre is one of Europe''s best interactive science museums for children. POLIN Museum of the History of Polish Jews is important and accessible. The Old Town is compact and very walkable.', 'Very safe. Standard precautions apply. Very welcoming to families with children.'),

('Zurich', 'Switzerland', 'CH', 'Switzerland''s financial capital combines pristine lakeside beauty, exceptional art museums, world-famous watches and chocolate, and easy access to the surrounding Alps for skiing and hiking.', ARRAY['lake','alps','chocolate','watches','culture'], 'June–September or December–February (skiing)', 'Europe/Zurich', 'CHF', 'German', 'Zoo Zurich is outstanding for families. Lake Zurich swimming is magical in summer. Lindt Home of Chocolate is a must for children. Swiss National Museum is free for children.', 'One of the world''s safest cities. Very family-friendly. Expensive but impeccably maintained infrastructure.')

